// The tester sets the conditions; the engine answers. Every change to the history asks
// again, so what the two agents say is derived rather than scripted. The request carries
// the whole history each time, which is what makes clearing it a client deleting a list.
async simQuote(log) {
  const history = (log || []).map(function (e) { return e.event_type; });
  this.set({ simLoading: true, simFault: '' });
  try {
    const res = await fetch(this.base() + '/api/simulate', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ baseline: this.state.committed, history: history })
    });
    const body = await res.json();
    if (!res.ok) {
      const detail = body.detail || {};
      throw new Error(detail.error || ('HTTP ' + res.status));
    }
    this.set({ simData: body, simLoading: false });
  } catch (e) {
    // Named rather than swallowed. An outcome the memories cannot read yet is a real
    // answer, and it is the server's sentence that says which one and why.
    this.set({ simData: null, simLoading: false, simFault: String(e.message || e) });
  }
}

